    36→        private bool _isInScope = false;
    37→        private readonly ILogger _logger;
    38→        private PreBlockCaches? PreBlockCaches { get; }
    39→        public bool IsWarmWorldState { get; }
    40→
    41→        public Hash256 StateRoot
    42→        {
    43→            get
    44→            {
    45→                GuardInScope();
