    55→        public WorldState(ITrieStore trieStore, IKeyValueStoreWithBatching? codeDb, ILogManager? logManager)
    56→            : this(trieStore, codeDb, logManager, null, null)
    57→        {
    58→        }
    59→
    60→        internal WorldState(
    61→            ITrieStore trieStore,
    62→            IKeyValueStoreWithBatching? codeDb,
    63→            ILogManager? logManager,
    64→            StateTree? stateTree = null,
    65→            IStorageTreeFactory? storageTreeFactory = null,
    66→            PreBlockCaches? preBlockCaches = null,
    67→            bool populatePreBlockCache = true)
    68→        {
    69→            PreBlockCaches = preBlockCaches;
    70→            IsWarmWorldState = !populatePreBlockCache;
    71→            _trieStore = trieStore;
    72→            _stateProvider = new StateProvider(trieStore.GetTrieStore(null), codeDb, logManager, stateTree, PreBlockCaches?.StateCache, populatePreBlockCache);
    73→            _persistentStorageProvider = new PersistentStorageProvider(trieStore, _stateProvider, logManager, storageTreeFactory, PreBlockCaches?.StorageCache, populatePreBlockCache);
    74→            _transientStorageProvider = new TransientStorageProvider(logManager);
    75→            _logger = logManager.GetClassLogger<WorldState>();
    76→        }
    77→
    78→        public WorldState(ITrieStore trieStore, IKeyValueStoreWithBatching? codeDb, ILogManager? logManager, PreBlockCaches? preBlockCaches, bool populatePreBlockCache = true)
    79→            : this(trieStore, codeDb, logManager, null, preBlockCaches: preBlockCaches, populatePreBlockCache: populatePreBlockCache)
    80→        {
    81→        }
    82→
    83→        [MethodImpl(MethodImplOptions.AggressiveInlining)]
    84→        private void GuardInScope()
    85→        {
    86→            if (!_isInScope) ThrowOutOfScope();
    87→        }
    88→
    89→        [MethodImpl(MethodImplOptions.AggressiveInlining)]
    90→        private void DebugGuardInScope()
    91→        {
    92→#if DEBUG
    93→            if (!_isInScope) ThrowOutOfScope();
    94→#endif
    95→        }
    96→
    97→        [StackTraceHidden, DoesNotReturn]
    98→        private void ThrowOutOfScope()
    99→        {
   100→            throw new InvalidOperationException($"{nameof(IWorldState)} must only be used within scope");
   101→        }
   102→
   103→        public Account GetAccount(Address address)
   104→        {
   105→            DebugGuardInScope();
   106→            return _stateProvider.GetAccount(address);
   107→        }
   108→
   109→        bool IAccountStateProvider.TryGetAccount(Address address, out AccountStruct account)
   110→        {
   111→            account = _stateProvider.GetAccount(address).ToStruct();
   112→            return !account.IsTotallyEmpty;
   113→        }
   114→
   115→        public bool IsContract(Address address)
   116→        {
   117→            DebugGuardInScope();
   118→            return _stateProvider.IsContract(address);
   119→        }
   120→
   121→        public byte[] GetOriginal(in StorageCell storageCell)
   122→        {
   123→            DebugGuardInScope();
   124→            return _persistentStorageProvider.GetOriginal(storageCell);
   125→        }
   126→        public ReadOnlySpan<byte> Get(in StorageCell storageCell)
   127→        {
   128→            DebugGuardInScope();
   129→            return _persistentStorageProvider.Get(storageCell);
   130→        }
   131→        public void Set(in StorageCell storageCell, byte[] newValue)
   132→        {
   133→            DebugGuardInScope();
   134→            _persistentStorageProvider.Set(storageCell, newValue);
   135→        }
   136→        public ReadOnlySpan<byte> GetTransientState(in StorageCell storageCell)
   137→        {
   138→            DebugGuardInScope();
   139→            return _transientStorageProvider.Get(storageCell);
   140→        }
   141→        public void SetTransientState(in StorageCell storageCell, byte[] newValue)
   142→        {
   143→            DebugGuardInScope();
   144→            _transientStorageProvider.Set(storageCell, newValue);
   145→        }
   146→        public void Reset(bool resetBlockChanges = true)
   147→        {
   148→            DebugGuardInScope();
   149→            _stateProvider.Reset(resetBlockChanges);
   150→            _persistentStorageProvider.Reset(resetBlockChanges);
   151→            _transientStorageProvider.Reset(resetBlockChanges);
   152→        }
   153→        public void WarmUp(AccessList? accessList)
   154→        {
   155→            if (accessList?.IsEmpty == false)
   156→            {
   157→                foreach ((Address address, AccessList.StorageKeysEnumerable storages) in accessList)
   158→                {
   159→                    bool exists = _stateProvider.WarmUp(address);
   160→                    foreach (UInt256 storage in storages)
   161→                    {
   162→                        _persistentStorageProvider.WarmUp(new StorageCell(address, in storage), isEmpty: !exists);
   163→                    }
   164→                }
   165→            }
   166→        }
   167→
   168→        public void WarmUp(Address address) => _stateProvider.WarmUp(address);
   169→        public void ClearStorage(Address address)
   170→        {
