   226→        public void CommitTree(long blockNumber)
   227→        {
   228→            DebugGuardInScope();
   229→            using (IBlockCommitter committer = _trieStore.BeginBlockCommit(blockNumber))
   230→            {
   231→                _persistentStorageProvider.CommitTrees(committer);
   232→                _stateProvider.CommitTree();
   233→            }
   234→            _persistentStorageProvider.StateRoot = _stateProvider.StateRoot;
   235→        }
