   237→        public UInt256 GetNonce(Address address)
   238→        {
   239→            DebugGuardInScope();
   240→            return _stateProvider.GetNonce(address);
   241→        }
   242→
   243→        public IDisposable BeginScope(BlockHeader? baseBlock)
   244→        {
   245→            if (_isInScope) throw new InvalidOperationException("Cannot create nested worldstate scope.");
   246→            _isInScope = true;
   247→
   248→            if (_logger.IsTrace) _logger.Trace($"Beginning WorldState scope with baseblock {baseBlock?.ToString(BlockHeader.Format.Short) ?? "null"} with stateroot {baseBlock?.StateRoot?.ToString() ?? "null"}.");
   249→
   250→            StateRoot = baseBlock?.StateRoot ?? Keccak.EmptyTreeHash;
   251→            IDisposable trieStoreCloser = _trieStore.BeginScope(baseBlock);
   252→
   253→            return new Reactive.AnonymousDisposable(() =>
   254→            {
   255→                Reset();
   256→                StateRoot = Keccak.EmptyTreeHash;
   257→                trieStoreCloser.Dispose();
   258→                _isInScope = false;
   259→                if (_logger.IsTrace) _logger.Trace($"WorldState scope for baseblock {baseBlock?.ToString(BlockHeader.Format.Short) ?? "null"} closed");
   260→            });
   261→        }
