   509→        public void Commit(IReleaseSpec releaseSpec, bool commitRoots, bool isGenesis)
   510→            => Commit(releaseSpec, NullStateTracer.Instance, commitRoots, isGenesis);
   511→
   512→        public void Commit(IReleaseSpec releaseSpec, IWorldStateTracer stateTracer, bool commitRoots, bool isGenesis)
   513→        {
   514→            Task codeFlushTask = !commitRoots || _codeBatch is null || _codeBatch.Count == 0
   515→                ? Task.CompletedTask
   516→                : CommitCodeAsync();
   517→
   518→            bool isTracing = _logger.IsTrace;
   519→            int stepsBack = _changes.Count - 1;
   520→            if (stepsBack < 0)
   521→            {
   522→                if (isTracing) TraceNoChanges();
   523→                if (commitRoots)
   524→                {
   525→                    FlushToTree();
   526→                }
   527→                return;
   528→            }
   529→
   530→            if (isTracing) TraceCommit(stepsBack);
   531→            if (_changes[stepsBack].IsNull)
   532→            {
   533→                ThrowStartOfCommitIsNull(stepsBack);
   534→            }
   535→
   536→            Dictionary<AddressAsKey, ChangeTrace>? trace = !stateTracer.IsTracingState ? null : [];
   537→
   538→            ReadOnlySpan<Change> changes = CollectionsMarshal.AsSpan(_changes);
   539→            for (int i = 0; i <= stepsBack; i++)
   540→            {
   541→                ref readonly Change change = ref changes[stepsBack - i];
   542→                if (trace is null && change!.ChangeType == ChangeType.JustCache)
   543→                {
   544→                    continue;
   545→                }
   546→
   547→                if (_committedThisRound.Contains(change!.Address))
   548→                {
   549→                    if (change.ChangeType == ChangeType.JustCache)
   550→                    {
   551→                        trace?.UpdateTrace(change.Address, change.Account);
   552→                    }
   553→
   554→                    continue;
   555→                }
   556→
   557→                // because it was not committed yet it means that the just cache is the only state (so it was read only)
   558→                if (trace is not null && change.ChangeType == ChangeType.JustCache)
   559→                {
   560→                    _nullAccountReads.Add(change.Address);
   561→                    continue;
   562→                }
   563→
   564→                Stack<int> stack = _intraTxCache[change.Address];
   565→                int forAssertion = stack.Pop();
   566→                if (forAssertion != stepsBack - i)
   567→                {
   568→                    ThrowUnexpectedPosition(stepsBack, i, forAssertion);
   569→                }
   570→
   571→                _committedThisRound.Add(change.Address);
   572→
   573→                switch (change.ChangeType)
   574→                {
   575→                    case ChangeType.JustCache:
   576→                        break;
   577→                    case ChangeType.Touch:
   578→                    case ChangeType.Update:
   579→                        {
   580→                            if (releaseSpec.IsEip158Enabled && change.Account.IsEmpty && !isGenesis)
   581→                            {
   582→                                if (isTracing) TraceRemoveEmpty(change);
   583→                                SetState(change.Address, null);
   584→                                trace?.AddToTrace(change.Address, null);
   585→                            }
   586→                            else
   587→                            {
   588→                                if (isTracing) TraceUpdate(change);
   589→                                SetState(change.Address, change.Account);
   590→                                trace?.AddToTrace(change.Address, change.Account);
   591→                            }
   592→
   593→                            break;
   594→                        }
   595→                    case ChangeType.New:
   596→                        {
   597→                            if (!releaseSpec.IsEip158Enabled || !change.Account.IsEmpty || isGenesis)
   598→                            {
   599→                                if (isTracing) TraceCreate(change);
   600→                                SetState(change.Address, change.Account);
   601→                                trace?.AddToTrace(change.Address, change.Account);
   602→                            }
   603→
   604→                            break;
   605→                        }
   606→                    case ChangeType.Delete:
   607→                        {
   608→                            if (isTracing) TraceRemove(change);
   609→                            bool wasItCreatedNow = false;
   610→                            while (stack.Count > 0)
   611→                            {
   612→                                int previousOne = stack.Pop();
   613→                                wasItCreatedNow |= _changes[previousOne].ChangeType == ChangeType.New;
   614→                                if (wasItCreatedNow)
   615→                                {
   616→                                    break;
   617→                                }
   618→                            }
   619→
   620→                            if (!wasItCreatedNow)
   621→                            {
   622→                                SetState(change.Address, null);
   623→                                trace?.AddToTrace(change.Address, null);
   624→                            }
   625→
   626→                            break;
   627→                        }
   628→                    default:
   629→                        ThrowUnknownChangeType();
   630→                        break;
   631→                }
   632→            }
   633→
   634→            trace?.ReportStateTrace(stateTracer, _nullAccountReads, this);
   635→
   636→            _changes.Clear();
   637→            _committedThisRound.Clear();
   638→            _nullAccountReads.Clear();
   639→            _intraTxCache.Clear();
   640→
   641→            if (commitRoots)
   642→            {
   643→                FlushToTree();
   644→            }
   645→
   646→            codeFlushTask.GetAwaiter().GetResult();
   647→
   648→            Task CommitCodeAsync()
   649→            {
   650→                Dictionary<Hash256AsKey, byte[]> dict = Interlocked.Exchange(ref _codeBatch, null);
   651→                if (dict is null) return Task.CompletedTask;
   652→                _codeBatchAlternate = default;
   653→
   654→                return Task.Run(() =>
   655→                {
   656→                    using (var batch = _codeDb.StartWriteBatch())
   657→                    {
   658→                        // Insert ordered for improved performance
   659→                        foreach (var kvp in dict.OrderBy(static kvp => kvp.Key))
   660→                        {
   661→                            batch.PutSpan(kvp.Key.Value.Bytes, kvp.Value);
   662→                        }
   663→                    }
   664→
   665→                    // Reuse Dictionary if not already re-initialized
   666→                    dict.Clear();
   667→                    if (Interlocked.CompareExchange(ref _codeBatch, dict, null) is null)
   668→                    {
   669→                        _codeBatchAlternate = _codeBatch.GetAlternateLookup<ValueHash256>();
   670→                    }
   671→                });
   672→            }
   673→
